import { expect, test, uniqueName } from "../../fixtures";

test("a file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
  // Arrange: a draft vendor owned by the signed-in member's tenant
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC05 Vendor"),
      category: "services",
      contact_email: `ops.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = (await vendorRes.json()) as { id: string };

  // Act: upload exactly 10 MiB of text
  const file = Buffer.alloc(10 * 1024 * 1024, "a");
  const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "contract",
      file: { name: "contract-10mib.txt", mimeType: "text/plain", buffer: file },
    },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
});
